  "description": "Illustrates the historical significance rating scale.",
  "definition": "A numerical scale typically ranging from 1-10, where 1-3 indicates minor historical significance, 4-7 indicates moderate significance, and 8-10 indicates exceptional historical importance."
}

{
  "id": 9,
  "knowledge": "Conservation Budget Efficiency (CBE)",
  "description": "Measures the efficiency of conservation budget allocation relative to artifact importance.",
  "definition": "Calculated as the average of the product of each artifact's 'Conservation Priority Index (CPI)' and its allocated budget ratio. The budget ratio is the proportion of the total conservation budget allocated to that artifact."
}

{
  "id": 36,
  "knowledge": "Conservation Resource Allocation Efficiency (CRAE)",
  "description": "Measures how efficiently conservation resources are allocated based on priorities and budget.",
  "definition": "Calculated as: 'Conservation Budget Efficiency (CBE)' * (1 - ('Conservation Backlog Risk (CBR)' / 10)). Higher values indicate more efficient allocation."
}

